// RTSS Overlay Preset — does the foreground game ship a frame generation library?
//
// The overlay cannot see which frames are generated by in-game frame generation (DLSS-G, FSR FG, XeSS-FG):
// PresentMon marks only driver-level generation. So the overlay guesses by the frame rhythm (every second
// frame is much cheaper for the GPU), and this probe is the second, independent condition: the game must have
// a frame generation library at all. A game without one is never reported as using frame generation, even if
// its own rendering alternates heavy and light frames.
//
// How: the foreground window's process is checked for loaded FG modules (Streamline DLSS-G, AMD FidelityFX,
// Intel XeSS-FG). FSR 3.0 is often linked statically into the game executable (e.g. Black Myth: Wukong), so if
// no module is found, the executable file is scanned once for FSR 3 frame interpolation symbols; the result is
// cached per path + size + timestamp in %ProgramData%\RTSS-Overlay-Preset\fg-cache.txt.
//
// Exported sensor: /overlay-preset/fg/data/0 "Frame Generation Library" = 1 or 0.
using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;

namespace Exporter
{
	static class FrameGenProbe
	{
		// module names (lower case) that mean "this game can generate frames"
		static readonly string[] s_modules =
		{
			"sl.dlss_g.dll", "nvngx_dlssg.dll",										// NVIDIA DLSS frame generation (Streamline)
			"amd_fidelityfx_dx12.dll", "amd_fidelityfx_vk.dll",						// AMD FidelityFX API (FSR 3.1+)
			"amd_fidelityfx_framegeneration_dx12.dll",								// FidelityFX SDK 2.x
			"ffx_frameinterpolation_x64.dll", "ffx_fsr3_x64.dll", "ffx_fsr3_dx12_x64.dll",	// FSR 3.0 as DLLs
			"libxess_fg.dll"														// Intel XeSS frame generation
		};
		// statically linked FSR 3 (FidelityFX SDK 1.x frame interpolation API)
		static readonly byte[] s_staticMarker = Encoding.ASCII.GetBytes("ffxFrameInterpolation");

		const int RECHECK_CALLS = 10;			// modules of the same process are re-read every 10 calls (~5 s)

		static int s_pid;
		static int s_calls;
		static int s_result;
		static readonly Dictionary<string, int> s_cache = LoadCache();
		static readonly HashSet<string> s_scanning = new HashSet<string>();
		static readonly object s_lock = new object();

		public static string ToXml()
		{
			int pid = ForegroundPid();
			if (pid != s_pid || s_calls % RECHECK_CALLS == 0)
			{
				s_pid = pid;
				s_result = pid > 0 ? Probe(pid) : 0;
			}
			s_calls++;

			return "<hardware>\n<id>/overlay-preset/fg</id><name>Frame Generation</name><type>Cpu</type>\n" +
				   "<sensor><id>/overlay-preset/fg/data/0</id><name>Frame Generation Library</name><type>Data</type><value>" +
				   s_result + "</value></sensor>\n</hardware>\n";
		}

		static int Probe(int pid)
		{
			string exe = null;
			bool modulesRead = false;
			IntPtr snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, (uint)pid);
			if (snap != INVALID_HANDLE_VALUE)
			{
				try
				{
					MODULEENTRY32W me = new MODULEENTRY32W();
					me.dwSize = (uint)Marshal.SizeOf(typeof(MODULEENTRY32W));
					for (bool ok = Module32FirstW(snap, ref me); ok; ok = Module32NextW(snap, ref me))
					{
						modulesRead = true;
						if (exe == null)
							exe = me.szExePath;		// the first module is the executable
						string name = me.szModule.ToLowerInvariant();
						foreach (string m in s_modules)
							if (name == m)
								return 1;
					}
				}
				finally
				{
					CloseHandle(snap);
				}
			}
			if (!modulesRead || exe == null)
				return 0;

			// no FG module loaded — look for statically linked FSR 3 in the executable (once per file version)
			string key;
			try
			{
				FileInfo fi = new FileInfo(exe);
				key = fi.FullName + "|" + fi.Length + "|" + fi.LastWriteTimeUtc.Ticks;
			}
			catch (Exception)
			{
				return 0;
			}

			lock (s_lock)
			{
				int cached;
				if (s_cache.TryGetValue(key, out cached))
					return cached;
				if (s_scanning.Add(key))
					ThreadPool.QueueUserWorkItem(delegate { Scan(exe, key); });
			}
			return 0;
		}

		static void Scan(string path, string key)
		{
			int found = 0;
			try
			{
				found = FileContains(path, s_staticMarker) ? 1 : 0;
			}
			catch (Exception)
			{
			}

			lock (s_lock)
			{
				s_cache[key] = found;
				s_scanning.Remove(key);
				SaveCache();
			}
		}

		static bool FileContains(string path, byte[] marker)
		{
			const int CHUNK = 4 * 1024 * 1024;
			byte[] buf = new byte[CHUNK + marker.Length];
			using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete, 1 << 16))
			{
				int carry = 0;
				while (true)
				{
					int read = fs.Read(buf, carry, CHUNK);
					if (read <= 0)
						return false;
					int len = carry + read;
					for (int i = 0; i <= len - marker.Length; i++)
					{
						if (buf[i] != marker[0])
							continue;
						int j = 1;
						while (j < marker.Length && buf[i + j] == marker[j])
							j++;
						if (j == marker.Length)
							return true;
					}
					// keep the tail: the marker may cross the chunk border
					carry = Math.Min(marker.Length - 1, len);
					Buffer.BlockCopy(buf, len - carry, buf, 0, carry);
				}
			}
		}

		static string CachePath()
		{
			return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "RTSS-Overlay-Preset", "fg-cache.txt");
		}

		static Dictionary<string, int> LoadCache()
		{
			Dictionary<string, int> cache = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
			try
			{
				string file = CachePath();
				if (File.Exists(file))
				{
					foreach (string line in File.ReadAllLines(file, Encoding.UTF8))
					{
						int tab = line.IndexOf('\t');
						if (tab > 0)
							cache[line.Substring(tab + 1)] = line[0] == '1' ? 1 : 0;
					}
				}
			}
			catch (Exception)
			{
			}
			return cache;
		}

		static void SaveCache()
		{
			try
			{
				string file = CachePath();
				Directory.CreateDirectory(Path.GetDirectoryName(file));
				StringBuilder sb = new StringBuilder();
				foreach (KeyValuePair<string, int> kv in s_cache)
					sb.Append(kv.Value).Append('\t').Append(kv.Key).Append("\r\n");
				File.WriteAllText(file, sb.ToString(), Encoding.UTF8);
			}
			catch (Exception)
			{
			}
		}

		static int ForegroundPid()
		{
			IntPtr wnd = GetForegroundWindow();
			if (wnd == IntPtr.Zero)
				return 0;
			uint pid;
			GetWindowThreadProcessId(wnd, out pid);
			return (int)pid;
		}

		const uint TH32CS_SNAPMODULE	= 0x00000008;
		const uint TH32CS_SNAPMODULE32	= 0x00000010;
		static readonly IntPtr INVALID_HANDLE_VALUE = new IntPtr(-1);

		[StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
		struct MODULEENTRY32W
		{
			public uint dwSize;
			public uint th32ModuleID;
			public uint th32ProcessID;
			public uint GlblcntUsage;
			public uint ProccntUsage;
			public IntPtr modBaseAddr;
			public uint modBaseSize;
			public IntPtr hModule;
			[MarshalAs(UnmanagedType.ByValTStr, SizeConst = 256)] public string szModule;
			[MarshalAs(UnmanagedType.ByValTStr, SizeConst = 260)] public string szExePath;
		}

		[DllImport("kernel32.dll", SetLastError = true)] static extern IntPtr CreateToolhelp32Snapshot(uint flags, uint pid);
		[DllImport("kernel32.dll", CharSet = CharSet.Unicode)] static extern bool Module32FirstW(IntPtr snap, ref MODULEENTRY32W me);
		[DllImport("kernel32.dll", CharSet = CharSet.Unicode)] static extern bool Module32NextW(IntPtr snap, ref MODULEENTRY32W me);
		[DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr handle);
		[DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
		[DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr wnd, out uint pid);
	}
}
